INSERT INTO "TutorApplications" ("Id", "UserId", "Bio", "Education", "University", "Major", "DegreeLevel", "Certifications", "Subject", "SubjectSub", "ExperienceYears", "Methodology", "Achievements", "DocumentsJson", "Status", "SubmittedAt", "RejectionReason", "ReviewedByAdminId", "ReviewedAt") VALUES
    ('81298c9a-1caa-5a2c-bf27-d8171d312a56', 'c28d2cc3-4655-53a1-a733-d36cda1a8547', 'Cựu thủ khoa đầu ra Viện Toán ứng dụng ĐH Bách Khoa. Hơn 6 năm kinh nghiệm luyện thi THPT Quốc gia môn Toán và Đánh giá năng lực ĐHQG. Phong cách giảng dạy logic, trực quan, chuyên trị các câu hỏi vận dụng cao 8.5+.', 'Thạc sĩ Toán ứng dụng - ĐH Bách Khoa Hà Nội', 'Đại học Quốc gia', 'Sư phạm & Chuyên ngành liên quan', 'Thạc sĩ / Cử nhân', 'Chứng chỉ nghiệp vụ sư phạm & Chứng chỉ chuyên môn', 'Giáo dục', 'Toàn diện', 6, 'Lấy người học làm trung tâm, phương pháp phản xạ và tư duy logic', 'Nhiều học viên đạt điểm cao trong các kỳ thi quốc gia', '[{"title":"Bằng cấp & Chứng chỉ","url":"https://example.com/cert.pdf"}]'::jsonb, 'Approved', CURRENT_TIMESTAMP + INTERVAL '-250000 minutes', NULL, 'aad42c85-d4c3-5a12-888c-74cb36911fce', CURRENT_TIMESTAMP + INTERVAL '-240000 minutes'),
    ('a55914dc-6919-525d-b7dc-7b262a70a23d', '1f388d54-34fa-5705-9d63-7c2ee342784f', 'IELTS 8.5 (Listening 9.0, Reading 9.0, Writing 8.0, Speaking 8.0). Từng làm việc tại các trung tâm quốc tế lớn. Phương pháp học cá nhân hóa theo band điểm, tập trung rèn tư duy phản biện trong Writing và phát âm chuẩn tự nhiên trong Speaking.', 'Cử nhân Kinh tế Quốc tế - ĐH Ngoại Thương Hà Nội (IELTS 8.5 Overall)', 'Đại học Quốc gia', 'Sư phạm & Chuyên ngành liên quan', 'Thạc sĩ / Cử nhân', 'Chứng chỉ nghiệp vụ sư phạm & Chứng chỉ chuyên môn', 'Giáo dục', 'Toàn diện', 5, 'Lấy người học làm trung tâm, phương pháp phản xạ và tư duy logic', 'Nhiều học viên đạt điểm cao trong các kỳ thi quốc gia', '[{"title":"Bằng cấp & Chứng chỉ","url":"https://example.com/cert.pdf"}]'::jsonb, 'Approved', CURRENT_TIMESTAMP + INTERVAL '-250000 minutes', NULL, 'aad42c85-d4c3-5a12-888c-74cb36911fce', CURRENT_TIMESTAMP + INTERVAL '-240000 minutes'),
    ('dbe74c73-d6c6-511f-af23-87779f55e2ae', '9b53d6a2-e156-5d85-a9ca-9182fe0c0609', 'Senior Software Engineer tại tập đoàn công nghệ lớn. Chuyên giảng dạy Python từ số 0, thuật toán, tư duy lập trình và xây dựng các dự án web thực chiến. Học viên được hướng dẫn làm project thực tế để đưa vào CV ứng tuyển.', 'Kỹ sư Khoa học Máy tính - ĐH Bách Khoa TP.HCM', 'Đại học Quốc gia', 'Sư phạm & Chuyên ngành liên quan', 'Thạc sĩ / Cử nhân', 'Chứng chỉ nghiệp vụ sư phạm & Chứng chỉ chuyên môn', 'Giáo dục', 'Toàn diện', 4, 'Lấy người học làm trung tâm, phương pháp phản xạ và tư duy logic', 'Nhiều học viên đạt điểm cao trong các kỳ thi quốc gia', '[{"title":"Bằng cấp & Chứng chỉ","url":"https://example.com/cert.pdf"}]'::jsonb, 'Approved', CURRENT_TIMESTAMP + INTERVAL '-250000 minutes', NULL, 'aad42c85-d4c3-5a12-888c-74cb36911fce', CURRENT_TIMESTAMP + INTERVAL '-240000 minutes'),
    ('c22927a4-d4cf-5f7c-aa13-4d481bc3fe22', '28d5ca66-216d-59ec-8f42-cce2d218a602', 'Giáo viên trường chuyên với hơn 8 năm giảng dạy Ngữ văn lớp 9, 10, 12 và luyện thi tuyển sinh. Giúp học sinh nắm vững cấu trúc bài văn nghị luận xã hội, mở rộng liên hệ thực tế và cách khai thác tác phẩm sâu sắc, đạt điểm 8+ nhẹ nhàng.', 'Thạc sĩ Văn học Việt Nam - ĐH Sư Phạm Hà Nội', 'Đại học Quốc gia', 'Sư phạm & Chuyên ngành liên quan', 'Thạc sĩ / Cử nhân', 'Chứng chỉ nghiệp vụ sư phạm & Chứng chỉ chuyên môn', 'Giáo dục', 'Toàn diện', 8, 'Lấy người học làm trung tâm, phương pháp phản xạ và tư duy logic', 'Nhiều học viên đạt điểm cao trong các kỳ thi quốc gia', '[{"title":"Bằng cấp & Chứng chỉ","url":"https://example.com/cert.pdf"}]'::jsonb, 'Approved', CURRENT_TIMESTAMP + INTERVAL '-250000 minutes', NULL, 'aad42c85-d4c3-5a12-888c-74cb36911fce', CURRENT_TIMESTAMP + INTERVAL '-240000 minutes'),
    ('b80e2297-8874-587d-82b9-d17607985799', '2e27d60c-da32-5632-a918-613daf719504', 'Giảng viên thỉnh giảng chuyên bồi dưỡng học sinh giỏi và luyện thi Đại học môn Vật lý. Phương pháp giải nhanh trắc nghiệm bằng sơ đồ tư duy và bản chất hiện tượng vật lý, không máy móc công thức.', 'Tiến sĩ Vật lý - ĐH Khoa học Tự nhiên ĐHQGHN', 'Đại học Quốc gia', 'Sư phạm & Chuyên ngành liên quan', 'Thạc sĩ / Cử nhân', 'Chứng chỉ nghiệp vụ sư phạm & Chứng chỉ chuyên môn', 'Giáo dục', 'Toàn diện', 7, 'Lấy người học làm trung tâm, phương pháp phản xạ và tư duy logic', 'Nhiều học viên đạt điểm cao trong các kỳ thi quốc gia', '[{"title":"Bằng cấp & Chứng chỉ","url":"https://example.com/cert.pdf"}]'::jsonb, 'Approved', CURRENT_TIMESTAMP + INTERVAL '-250000 minutes', NULL, 'aad42c85-d4c3-5a12-888c-74cb36911fce', CURRENT_TIMESTAMP + INTERVAL '-240000 minutes'),
    ('1d90fa49-122d-513a-8796-c374e083f7d3', '5cd6d5bf-5dbf-54d6-a46c-3518992be42a', 'Chuyên luyện thi Hóa học lớp 12 và kỳ thi tốt nghiệp THPT. Chuyên sâu các dạng bài tập este, lipit, amino axit và bài toán đồ thị vô cơ. Luôn đồng hành giải đáp thắc mắc 24/7 cho học viên.', 'Thạc sĩ Kỹ thuật Hóa học - ĐH Bách Khoa Hà Nội', 'Đại học Quốc gia', 'Sư phạm & Chuyên ngành liên quan', 'Thạc sĩ / Cử nhân', 'Chứng chỉ nghiệp vụ sư phạm & Chứng chỉ chuyên môn', 'Giáo dục', 'Toàn diện', 5, 'Lấy người học làm trung tâm, phương pháp phản xạ và tư duy logic', 'Nhiều học viên đạt điểm cao trong các kỳ thi quốc gia', '[{"title":"Bằng cấp & Chứng chỉ","url":"https://example.com/cert.pdf"}]'::jsonb, 'Approved', CURRENT_TIMESTAMP + INTERVAL '-250000 minutes', NULL, 'aad42c85-d4c3-5a12-888c-74cb36911fce', CURRENT_TIMESTAMP + INTERVAL '-240000 minutes'),
    ('c59d8610-8721-52be-ab1f-3ecfc342563e', '4abadf29-26db-5c34-b7e4-1d39d442fdc4', 'Chuyên luyện thi TOEIC 2 kỹ năng & 4 kỹ năng cấp tốc cho sinh viên ra trường và người đi làm. Lộ trình tinh gọn từ 450 lên 750+ chỉ sau 2-3 tháng học tập trung, trang bị kỹ năng bắt bẫy đề thi hiệu quả.', 'Cử nhân Ngôn ngữ Anh - ĐH Ngoại Ngữ ĐHQGHN (TOEIC 985/990)', 'Đại học Quốc gia', 'Sư phạm & Chuyên ngành liên quan', 'Thạc sĩ / Cử nhân', 'Chứng chỉ nghiệp vụ sư phạm & Chứng chỉ chuyên môn', 'Giáo dục', 'Toàn diện', 4, 'Lấy người học làm trung tâm, phương pháp phản xạ và tư duy logic', 'Nhiều học viên đạt điểm cao trong các kỳ thi quốc gia', '[{"title":"Bằng cấp & Chứng chỉ","url":"https://example.com/cert.pdf"}]'::jsonb, 'Approved', CURRENT_TIMESTAMP + INTERVAL '-250000 minutes', NULL, 'aad42c85-d4c3-5a12-888c-74cb36911fce', CURRENT_TIMESTAMP + INTERVAL '-240000 minutes'),
    ('65ff409b-e620-5864-997d-d015cbbaf70b', '5dd69c3b-f5a0-5b01-b2d1-afccfd1faa9d', 'Tốt nghiệp thủ khoa tại Bắc Kinh, 6 năm giảng dạy tiếng Trung từ sơ cấp HSK 1 đến cao cấp HSK 6. Phát âm Bắc Kinh chuẩn xác, bài giảng kết hợp yếu tố văn hóa thú vị, dễ tiếp thu cho người mới bắt đầu.', 'Thạc sĩ Hán ngữ đối ngoại - ĐH Ngôn ngữ Bắc Kinh (HSK 6)', 'Đại học Quốc gia', 'Sư phạm & Chuyên ngành liên quan', 'Thạc sĩ / Cử nhân', 'Chứng chỉ nghiệp vụ sư phạm & Chứng chỉ chuyên môn', 'Giáo dục', 'Toàn diện', 6, 'Lấy người học làm trung tâm, phương pháp phản xạ và tư duy logic', 'Nhiều học viên đạt điểm cao trong các kỳ thi quốc gia', '[{"title":"Bằng cấp & Chứng chỉ","url":"https://example.com/cert.pdf"}]'::jsonb, 'Approved', CURRENT_TIMESTAMP + INTERVAL '-250000 minutes', NULL, 'aad42c85-d4c3-5a12-888c-74cb36911fce', CURRENT_TIMESTAMP + INTERVAL '-240000 minutes'),
    ('39b1fd9f-54b3-50f2-b798-7e82eb7c6cb7', 'c124e1c8-8bfa-5b50-805f-8847916e247b', 'Fullstack Developer & Mentor lập trình. Chuyên đào tạo HTML/CSS/JavaScript hiện đại, React.js, Tailwind CSS và làm việc cùng RESTful API. Cam kết kèm cặp 1-1 từng dòng code tới khi ra được sản phẩm thực tế.', 'Thạc sĩ Mạng máy tính & Viễn thông - ĐH Bách Khoa', 'Đại học Quốc gia', 'Sư phạm & Chuyên ngành liên quan', 'Thạc sĩ / Cử nhân', 'Chứng chỉ nghiệp vụ sư phạm & Chứng chỉ chuyên môn', 'Giáo dục', 'Toàn diện', 5, 'Lấy người học làm trung tâm, phương pháp phản xạ và tư duy logic', 'Nhiều học viên đạt điểm cao trong các kỳ thi quốc gia', '[{"title":"Bằng cấp & Chứng chỉ","url":"https://example.com/cert.pdf"}]'::jsonb, 'Approved', CURRENT_TIMESTAMP + INTERVAL '-250000 minutes', NULL, 'aad42c85-d4c3-5a12-888c-74cb36911fce', CURRENT_TIMESTAMP + INTERVAL '-240000 minutes'),
    ('e67297c9-9c8a-5e13-87b5-6a271036b5c3', '9a3b414d-feda-5a7d-81b0-046cbc3f9042', 'Đạt JLPT N1 năm 21 tuổi, từng du học và làm việc tại Tokyo 3 năm. Hướng dẫn lộ trình từ N5 đến N2 mạch lạc, chú trọng từ vựng Kanji qua câu chuyện và phản xạ nghe nói thực tế.', 'Cử nhân Sư phạm Tiếng Nhật - ĐH Ngoại ngữ Hà Nội (JLPT N1)', 'Đại học Quốc gia', 'Sư phạm & Chuyên ngành liên quan', 'Thạc sĩ / Cử nhân', 'Chứng chỉ nghiệp vụ sư phạm & Chứng chỉ chuyên môn', 'Giáo dục', 'Toàn diện', 5, 'Lấy người học làm trung tâm, phương pháp phản xạ và tư duy logic', 'Nhiều học viên đạt điểm cao trong các kỳ thi quốc gia', '[{"title":"Bằng cấp & Chứng chỉ","url":"https://example.com/cert.pdf"}]'::jsonb, 'Approved', CURRENT_TIMESTAMP + INTERVAL '-250000 minutes', NULL, 'aad42c85-d4c3-5a12-888c-74cb36911fce', CURRENT_TIMESTAMP + INTERVAL '-240000 minutes'),
    ('29ac2a6f-b96f-52fb-bb01-5731a0939f82', '3fc6d606-57c4-5ded-bd09-fb125bb19ffc', 'Chuyên gia dạy kèm Tiếng Anh cấp 2, cấp 3 và luyện thi vào 10 chuyên Anh. Bài giảng sinh động, tạo động lực cao và cải thiện rõ rệt điểm số trên lớp cho học sinh bị mất gốc.', 'Thủ khoa khối D1 tỉnh Nam Định - ĐH Ngoại Thương (IELTS 8.0)', 'Đại học Quốc gia', 'Sư phạm & Chuyên ngành liên quan', 'Thạc sĩ / Cử nhân', 'Chứng chỉ nghiệp vụ sư phạm & Chứng chỉ chuyên môn', 'Giáo dục', 'Toàn diện', 3, 'Lấy người học làm trung tâm, phương pháp phản xạ và tư duy logic', 'Nhiều học viên đạt điểm cao trong các kỳ thi quốc gia', '[{"title":"Bằng cấp & Chứng chỉ","url":"https://example.com/cert.pdf"}]'::jsonb, 'Approved', CURRENT_TIMESTAMP + INTERVAL '-250000 minutes', NULL, 'aad42c85-d4c3-5a12-888c-74cb36911fce', CURRENT_TIMESTAMP + INTERVAL '-240000 minutes'),
    ('fd45de41-7538-5658-8ad8-1fc4a1248daa', '723d6f05-3b61-5901-841e-c3c2d8dfcdbb', 'Chuyên đào tạo kỹ năng tư duy logic, phương pháp ghi nhớ siêu tốc và kỹ năng thuyết trình cho học sinh, sinh viên. Giúp người học tự tin làm chủ bài thuyết trình và xây dựng thói quen tự học trọn đời.', 'Thạc sĩ Phương pháp Giảng dạy - ĐH Giáo dục ĐHQGHN', 'Đại học Quốc gia', 'Sư phạm & Chuyên ngành liên quan', 'Thạc sĩ / Cử nhân', 'Chứng chỉ nghiệp vụ sư phạm & Chứng chỉ chuyên môn', 'Giáo dục', 'Toàn diện', 6, 'Lấy người học làm trung tâm, phương pháp phản xạ và tư duy logic', 'Nhiều học viên đạt điểm cao trong các kỳ thi quốc gia', '[{"title":"Bằng cấp & Chứng chỉ","url":"https://example.com/cert.pdf"}]'::jsonb, 'Approved', CURRENT_TIMESTAMP + INTERVAL '-250000 minutes', NULL, 'aad42c85-d4c3-5a12-888c-74cb36911fce', CURRENT_TIMESTAMP + INTERVAL '-240000 minutes');
