INSERT INTO "TutorProfiles" ("Id", "UserId", "Bio", "Education", "ExperienceYears", "RatingAvg", "TotalReviews", "BankName", "BankCode", "AccountNumber", "AccountHolderName") VALUES
    ('73d0cea4-4a18-54d2-8735-e7ea844bf4b6', 'c28d2cc3-4655-53a1-a733-d36cda1a8547', 'Cựu thủ khoa đầu ra Viện Toán ứng dụng ĐH Bách Khoa. Hơn 6 năm kinh nghiệm luyện thi THPT Quốc gia môn Toán và Đánh giá năng lực ĐHQG. Phong cách giảng dạy logic, trực quan, chuyên trị các câu hỏi vận dụng cao 8.5+.', 'Thạc sĩ Toán ứng dụng - ĐH Bách Khoa Hà Nội', 6, 4.92, 28, 'Vietcombank', 'VCB', '0011004567890', 'DANG HOANG NAM'),
    ('388cc4b9-d24f-5513-b300-84802bdc9fc7', '1f388d54-34fa-5705-9d63-7c2ee342784f', 'IELTS 8.5 (Listening 9.0, Reading 9.0, Writing 8.0, Speaking 8.0). Từng làm việc tại các trung tâm quốc tế lớn. Phương pháp học cá nhân hóa theo band điểm, tập trung rèn tư duy phản biện trong Writing và phát âm chuẩn tự nhiên trong Speaking.', 'Cử nhân Kinh tế Quốc tế - ĐH Ngoại Thương Hà Nội (IELTS 8.5 Overall)', 5, 4.98, 42, 'Techcombank', 'TCB', '19034567891234', 'NGUYEN MAI CHI'),
    ('0fc9a7c2-76dd-52ed-97b4-85b8caaede73', '9b53d6a2-e156-5d85-a9ca-9182fe0c0609', 'Senior Software Engineer tại tập đoàn công nghệ lớn. Chuyên giảng dạy Python từ số 0, thuật toán, tư duy lập trình và xây dựng các dự án web thực chiến. Học viên được hướng dẫn làm project thực tế để đưa vào CV ứng tuyển.', 'Kỹ sư Khoa học Máy tính - ĐH Bách Khoa TP.HCM', 4, 4.90, 19, 'MBBank', 'MB', '080123456789', 'LE TUAN ANH'),
    ('b068a548-7db1-5635-af2d-afed58c62765', '28d5ca66-216d-59ec-8f42-cce2d218a602', 'Giáo viên trường chuyên với hơn 8 năm giảng dạy Ngữ văn lớp 9, 10, 12 và luyện thi tuyển sinh. Giúp học sinh nắm vững cấu trúc bài văn nghị luận xã hội, mở rộng liên hệ thực tế và cách khai thác tác phẩm sâu sắc, đạt điểm 8+ nhẹ nhàng.', 'Thạc sĩ Văn học Việt Nam - ĐH Sư Phạm Hà Nội', 8, 4.88, 31, 'BIDV', 'BIDV', '12310004567890', 'VU THU TRANG'),
    ('d11f7611-3cfc-5b72-86ec-a0385482912f', '2e27d60c-da32-5632-a918-613daf719504', 'Giảng viên thỉnh giảng chuyên bồi dưỡng học sinh giỏi và luyện thi Đại học môn Vật lý. Phương pháp giải nhanh trắc nghiệm bằng sơ đồ tư duy và bản chất hiện tượng vật lý, không máy móc công thức.', 'Tiến sĩ Vật lý - ĐH Khoa học Tự nhiên ĐHQGHN', 7, 4.95, 24, 'VietinBank', 'CTG', '103876543210', 'TRAN QUOC HUY'),
    ('c953a4f0-1a5a-5b43-85ec-8ac366f7103a', '5cd6d5bf-5dbf-54d6-a46c-3518992be42a', 'Chuyên luyện thi Hóa học lớp 12 và kỳ thi tốt nghiệp THPT. Chuyên sâu các dạng bài tập este, lipit, amino axit và bài toán đồ thị vô cơ. Luôn đồng hành giải đáp thắc mắc 24/7 cho học viên.', 'Thạc sĩ Kỹ thuật Hóa học - ĐH Bách Khoa Hà Nội', 5, 4.86, 18, 'ACB', 'ACB', '283746190', 'BUI THI PHUONG THAO'),
    ('6085aee4-99ad-552a-8f76-e66ebc3407ec', '4abadf29-26db-5c34-b7e4-1d39d442fdc4', 'Chuyên luyện thi TOEIC 2 kỹ năng & 4 kỹ năng cấp tốc cho sinh viên ra trường và người đi làm. Lộ trình tinh gọn từ 450 lên 750+ chỉ sau 2-3 tháng học tập trung, trang bị kỹ năng bắt bẫy đề thi hiệu quả.', 'Cử nhân Ngôn ngữ Anh - ĐH Ngoại Ngữ ĐHQGHN (TOEIC 985/990)', 4, 4.85, 22, 'Techcombank', 'TCB', '19038921829102', 'PHAM NHAT QUANG'),
    ('48579260-dd32-5fe8-a102-9da9005d01e2', '5dd69c3b-f5a0-5b01-b2d1-afccfd1faa9d', 'Tốt nghiệp thủ khoa tại Bắc Kinh, 6 năm giảng dạy tiếng Trung từ sơ cấp HSK 1 đến cao cấp HSK 6. Phát âm Bắc Kinh chuẩn xác, bài giảng kết hợp yếu tố văn hóa thú vị, dễ tiếp thu cho người mới bắt đầu.', 'Thạc sĩ Hán ngữ đối ngoại - ĐH Ngôn ngữ Bắc Kinh (HSK 6)', 6, 4.96, 36, 'Vietcombank', 'VCB', '0021008765432', 'DO QUYNH NGA'),
    ('09302f85-f449-5925-9392-b4cdb8e6c88a', 'c124e1c8-8bfa-5b50-805f-8847916e247b', 'Fullstack Developer & Mentor lập trình. Chuyên đào tạo HTML/CSS/JavaScript hiện đại, React.js, Tailwind CSS và làm việc cùng RESTful API. Cam kết kèm cặp 1-1 từng dòng code tới khi ra được sản phẩm thực tế.', 'Thạc sĩ Mạng máy tính & Viễn thông - ĐH Bách Khoa', 5, 4.89, 15, 'TPBank', 'TPB', '03928172601', 'HOANG DUC BAO'),
    ('1c34e3d2-e7f2-5b80-8975-ddd66051b020', '9a3b414d-feda-5a7d-81b0-046cbc3f9042', 'Đạt JLPT N1 năm 21 tuổi, từng du học và làm việc tại Tokyo 3 năm. Hướng dẫn lộ trình từ N5 đến N2 mạch lạc, chú trọng từ vựng Kanji qua câu chuyện và phản xạ nghe nói thực tế.', 'Cử nhân Sư phạm Tiếng Nhật - ĐH Ngoại ngữ Hà Nội (JLPT N1)', 5, 4.91, 20, 'VPBank', 'VPB', '1827364501', 'NGO MINH KHANG'),
    ('988f492c-d590-561d-8e77-244e62a56b21', '3fc6d606-57c4-5ded-bd09-fb125bb19ffc', 'Chuyên gia dạy kèm Tiếng Anh cấp 2, cấp 3 và luyện thi vào 10 chuyên Anh. Bài giảng sinh động, tạo động lực cao và cải thiện rõ rệt điểm số trên lớp cho học sinh bị mất gốc.', 'Thủ khoa khối D1 tỉnh Nam Định - ĐH Ngoại Thương (IELTS 8.0)', 3, 4.82, 14, 'Vietcombank', 'VCB', '0011009988776', 'NGUYEN HOANG YEN NHI'),
    ('9d9ce05e-9472-5fcd-96ba-819c70797fb0', '723d6f05-3b61-5901-841e-c3c2d8dfcdbb', 'Chuyên đào tạo kỹ năng tư duy logic, phương pháp ghi nhớ siêu tốc và kỹ năng thuyết trình cho học sinh, sinh viên. Giúp người học tự tin làm chủ bài thuyết trình và xây dựng thói quen tự học trọn đời.', 'Thạc sĩ Phương pháp Giảng dạy - ĐH Giáo dục ĐHQGHN', 6, 4.94, 26, 'MBBank', 'MB', '098765432101', 'TRINH GIA HUNG');
