INSERT INTO "Services" ("Id", "TutorProfileId", "SubjectId", "Title", "Description", "ShortDescription", "TagsJson", "LearningScope", "ExpectedOutcome", "TotalSessions", "SessionDurationMinutes", "Price", "TrialLessonUrl", "CoverImageUrl", "CurriculumJson", "TargetAudienceJson", "PrerequisitesJson", "FaqsJson", "Status", "CreatedAt", "UpdatedAt", "IsDeleted", "DeletedAt", "DeletedByUserId") VALUES
    ('1babaf2c-1376-5dc0-8d36-43b29880498d', '73d0cea4-4a18-54d2-8735-e7ea844bf4b6', 'd5dd47df-2a82-52d9-81dc-cfe748d036be', 'Chuyên đề Vận dụng cao Toán 12 (Mục tiêu 9+)', 'Khóa học chuyên sâu bẻ khóa các dạng toán hàm số, tích phân, hình không gian và xác suất thực tế dành cho học sinh khá giỏi.', 'Khóa học giải mã toàn bộ câu hỏi khó từ đề thi chính thức và đề thi thử các trường chuyên cả nước.', '["Toán 12","Luyện thi ĐH","Vận dụng cao 9+"]'::jsonb, 'Phù hợp học sinh, sinh viên và người có mục tiêu rõ ràng muốn đạt kết quả tốt nhất trong thời gian ngắn.', 'Nắm vững bản chất kiến thức, tự tin giải quyết bài toán và áp dụng linh hoạt vào thực tế.', 15, 90, 3750000, 'https://meet.google.com/test-tutorhub', 'https://images.unsplash.com/photo-1509228468518-180dd4864904?w=500', '[{"session":1,"topic":"Chuyên đề 1: Nội dung kiến thức cốt lõi và bài tập thực hành phần 1"},{"session":2,"topic":"Chuyên đề 2: Nội dung kiến thức cốt lõi và bài tập thực hành phần 2"},{"session":3,"topic":"Chuyên đề 3: Nội dung kiến thức cốt lõi và bài tập thực hành phần 3"},{"session":4,"topic":"Chuyên đề 4: Nội dung kiến thức cốt lõi và bài tập thực hành phần 4"},{"session":5,"topic":"Chuyên đề 5: Nội dung kiến thức cốt lõi và bài tập thực hành phần 5"},{"session":6,"topic":"Chuyên đề 6: Nội dung kiến thức cốt lõi và bài tập thực hành phần 6"},{"session":7,"topic":"Chuyên đề 7: Nội dung kiến thức cốt lõi và bài tập thực hành phần 7"},{"session":8,"topic":"Chuyên đề 8: Nội dung kiến thức cốt lõi và bài tập thực hành phần 8"},{"session":9,"topic":"Chuyên đề 9: Nội dung kiến thức cốt lõi và bài tập thực hành phần 9"},{"session":10,"topic":"Chuyên đề 10: Nội dung kiến thức cốt lõi và bài tập thực hành phần 10"},{"session":11,"topic":"Chuyên đề 11: Nội dung kiến thức cốt lõi và bài tập thực hành phần 11"},{"session":12,"topic":"Chuyên đề 12: Nội dung kiến thức cốt lõi và bài tập thực hành phần 12"},{"session":13,"topic":"Chuyên đề 13: Nội dung kiến thức cốt lõi và bài tập thực hành phần 13"},{"session":14,"topic":"Chuyên đề 14: Nội dung kiến thức cốt lõi và bài tập thực hành phần 14"},{"session":15,"topic":"Chuyên đề 15: Nội dung kiến thức cốt lõi và bài tập thực hành phần 15"}]'::jsonb, '["Học sinh THCS/THPT","Sinh viên","Người đi làm muốn nâng cao trình độ"]'::jsonb, '["Máy tính có kết nối Internet","Sách vở ghi chép"]'::jsonb, '[{"q":"Có được học bù nếu bận không?","a":"Học viên được đổi lịch trước tối thiểu 2 giờ theo quy định của nền tảng."}]'::jsonb, 'Published', CURRENT_TIMESTAMP + INTERVAL '-101000 minutes', CURRENT_TIMESTAMP + INTERVAL '-1000 minutes', FALSE, NULL, NULL),
    ('37e00e1c-e959-54d6-9a8d-8f9cd81e79ba', '73d0cea4-4a18-54d2-8735-e7ea844bf4b6', '0e548b99-6a86-5718-ba60-447d859eeb7c', 'Luyện thi Tư duy Định lượng ĐGNL ĐHQG', 'Khóa luyện đề thực chiến phân tích số liệu, tư duy logic và giải nhanh bài toán định lượng kỳ thi Đánh giá năng lực.', 'Trang bị đầy đủ kỹ năng giải toán tốc độ cao và phản xạ đề thi mẫu mới nhất.', '["ĐGNL","Tư duy toán","ĐHQG"]'::jsonb, 'Phù hợp học sinh, sinh viên và người có mục tiêu rõ ràng muốn đạt kết quả tốt nhất trong thời gian ngắn.', 'Nắm vững bản chất kiến thức, tự tin giải quyết bài toán và áp dụng linh hoạt vào thực tế.', 10, 90, 2500000, 'https://meet.google.com/test-tutorhub', 'https://images.unsplash.com/photo-1434030216411-0b793f4b4173?w=500', '[{"session":1,"topic":"Chuyên đề 1: Nội dung kiến thức cốt lõi và bài tập thực hành phần 1"},{"session":2,"topic":"Chuyên đề 2: Nội dung kiến thức cốt lõi và bài tập thực hành phần 2"},{"session":3,"topic":"Chuyên đề 3: Nội dung kiến thức cốt lõi và bài tập thực hành phần 3"},{"session":4,"topic":"Chuyên đề 4: Nội dung kiến thức cốt lõi và bài tập thực hành phần 4"},{"session":5,"topic":"Chuyên đề 5: Nội dung kiến thức cốt lõi và bài tập thực hành phần 5"},{"session":6,"topic":"Chuyên đề 6: Nội dung kiến thức cốt lõi và bài tập thực hành phần 6"},{"session":7,"topic":"Chuyên đề 7: Nội dung kiến thức cốt lõi và bài tập thực hành phần 7"},{"session":8,"topic":"Chuyên đề 8: Nội dung kiến thức cốt lõi và bài tập thực hành phần 8"},{"session":9,"topic":"Chuyên đề 9: Nội dung kiến thức cốt lõi và bài tập thực hành phần 9"},{"session":10,"topic":"Chuyên đề 10: Nội dung kiến thức cốt lõi và bài tập thực hành phần 10"}]'::jsonb, '["Học sinh THCS/THPT","Sinh viên","Người đi làm muốn nâng cao trình độ"]'::jsonb, '["Máy tính có kết nối Internet","Sách vở ghi chép"]'::jsonb, '[{"q":"Có được học bù nếu bận không?","a":"Học viên được đổi lịch trước tối thiểu 2 giờ theo quy định của nền tảng."}]'::jsonb, 'Published', CURRENT_TIMESTAMP + INTERVAL '-102000 minut