    ('856e3bb5-6807-5cec-94fc-6807b3666aac', 'f6fe5ef4-fd65-5b41-bdae-76f3f6ba4aa1', 5, 'Cô Chi sửa Writing cực kỳ kỹ lưỡng, chỉ rõ từng lỗi diễn đạt. Em đã tự tin hơn hẳn khi làm Task 2.', 'Cảm ơn em, tư duy phản biện của em tiến bộ rõ rệt qua từng bài.', CURRENT_TIMESTAMP + INTERVAL '-500 minutes', FALSE, NULL, NULL, NULL, CURRENT_TIMESTAMP + INTERVAL '-800 minutes'),
    ('e59f2e39-74fe-51cf-b989-1934d734094c', 'b39b7a9d-790a-56ca-86ac-482ada0e3ccf', 5, 'Bài giảng thực tế, cô đọng, code trực tiếp nên hiểu rất nhanh. Đáng từng đồng học phí!', 'Rất vui vì đã hỗ trợ được em trên con đường chinh phục công nghệ.', CURRENT_TIMESTAMP + INTERVAL '-500 minutes', FALSE, NULL, NULL, NULL, CURRENT_TIMESTAMP + INTERVAL '-800 minutes'),
    ('c539a91f-be41-5a4f-89ff-145bbc70dea5', '467ecf46-8158-5cd3-a455-90030f8bdb25', 5, 'Cô Chi sửa Writing cực kỳ kỹ lưỡng, chỉ rõ từng lỗi diễn đạt. Em đã tự tin hơn hẳn khi làm Task 2.', 'Cảm ơn em, tư duy phản biện của em tiến bộ rõ rệt qua từng bài.', CURRENT_TIMESTAMP + INTERVAL '-500 minutes', FALSE, NULL, NULL, NULL, CURRENT_TIMESTAMP + INTERVAL '-800 minutes'),
    ('b51fe834-a399-5ec2-ad6c-d87b7373162d', '94ad0c9a-a47a-5bb2-80d8-f94ab4dcc6ad', 5, 'Thầy dạy rất nhiệt tình, giải bài chi tiết và dễ hiểu. Nhờ thầy mà em thi thử tăng từ 6.8 lên 8.8!', 'Cảm ơn em đã chăm chỉ và nỗ lực rất nhiều. Chúc em thi thật tốt nhé!', CURRENT_TIMESTAMP + INTERVAL '-500 minutes', FALSE, NULL, NULL, NULL, CURRENT_TIMESTAMP + INTERVAL '-800 minutes'),
    ('b732e713-726f-568a-9c26-d84b217ee5f3', '4d9097c9-0bea-541d-933d-d32e2e5ed3d2', 5, 'Bài giảng thực tế, cô đọng, code trực tiếp nên hiểu rất nhanh. Đáng từng đồng học phí!', 'Rất vui vì đã hỗ trợ được em trên con đường chinh phục công nghệ.', CURRENT_TIMESTAMP + INTERVAL '-500 minutes', FALSE, NULL, NULL, NULL, CURRENT_TIMESTAMP + INTERVAL '-800 minutes');
